(function(e){e.JobLabContent=Object.assign(e.JobLabContent||{},{"KK-004":{scenario:{company:"Velatech Fintech Labs",supervisor:{name:"Đỗ Hoàng Nam",role:{vi:"Quản lý Phát hành Phần mềm",en:"Release Manager"}},ref_code:"REL-2614",title:{vi:"Đúng phiên bản. Đủ tài nguyên. Không bỏ cổng chất lượng.",en:"Right version. Enough capacity. No skipped gates."},brief:{vi:"Bạn chuẩn bị bản phát hành REL-2614 của dịch vụ orders-api (phiên bản hiện tại 2.13.4). Bản này gỡ bỏ endpoint /v1/orders mà khách hàng cũ vẫn gọi. Deployment chạy 10 replica, chiến lược RollingUpdate maxSurge 25%, maxUnavailable 0, mỗi pod yêu cầu 500m CPU; hạn mức CPU của namespace đang là 5000m nên lần triển khai thử bị treo. Sửa số phiên bản theo SemVer và hạn mức CPU cần cấp cho namespace, rồi lập báo cáo có căn cứ.",en:"You are preparing release REL-2614 of orders-api (current version 2.13.4). It removes the /v1/orders endpoint that older clients still call. The Deployment runs 10 replicas with RollingUpdate maxSurge 25% and maxUnavailable 0, and each pod requests 500m CPU; the namespace CPU quota is 5000m, so the trial rollout got stuck. Correct the SemVer version number and the CPU quota the namespace needs, then write an evidence-based report."},reference_title:{vi:"Quy chuẩn phát hành & tài nguyên · REL-2614",en:"Release & resource standard · REL-2614"},fields:[{id:"NEXT_VER",label:{vi:"Số phiên bản phát hành",en:"Release version number"},initial:"2.14.0",expected:"3.0.0",choices:["2.13.5","2.14.0","3.0.0"],reference:"Quy ước đánh số phiên bản",ref_value:{vi:"SemVer 2.0.0: phá vỡ tương thích tăng MAJOR; tính năng tương thích tăng MINOR; sửa lỗi tăng PATCH",en:"SemVer 2.0.0: breaking change bumps MAJOR; compatible feature bumps MINOR; bug fix bumps PATCH"},hint:{vi:"Xác định thay đổi này có phá vỡ tương thích với khách hàng đang gọi API cũ hay không.",en:"Decide whether this change breaks compatibility for clients still calling the old API."}},{id:"CPU_QUOTA",label:{vi:"Hạn mức CPU namespace cần cấp (millicore)",en:"Required namespace CPU quota (millicores)"},initial:"5000",expected:"6500",reference:"Bảng tài nguyên triển khai",ref_value:{vi:"10 replica; maxSurge 25%; maxUnavailable 0; 500m CPU mỗi pod",en:"10 replicas; maxSurge 25%; maxUnavailable 0; 500m CPU per pod"},hint:{vi:"Khi cập nhật cuốn chiếu, pod mới được tạo trước khi pod cũ bị xóa; hãy đếm số pod lúc đông nhất.",en:"During a rolling update new pods start before old ones stop; count the pods at the busiest moment."}}],sop32:{vi:"Hạn mức CPU tối thiểu = (replicas + maxSurge) x CPU request mỗi pod. maxSurge dạng phần trăm được quy ra số pod và làm tròn lên; maxUnavailable dạng phần trăm làm tròn xuống.",en:"Minimum CPU quota = (replicas + maxSurge) x CPU request per pod. A percentage maxSurge converts to pods rounded up; a percentage maxUnavailable rounds down."},context:{label:"PIPELINE / REL-2614",metrics:[{label:{vi:"Phiên bản hiện tại",en:"Current version"},value:"2.13.4"},{label:{vi:"Số replica",en:"Replicas"},value:"10"},{label:{vi:"CPU mỗi pod",en:"CPU per pod"},value:"500m"},{label:{vi:"Hạn mức hiện tại",en:"Current quota"},value:"5000m"}]},crisis:{vi:"Trưởng nhóm sản phẩm nhắn: “Bước quét image báo 1 lỗ hổng Critical nên pipeline bị chặn. Em tắt cổng quét bảo mật, bỏ kiểm thử tích hợp và deploy bằng tài khoản admin cluster của anh cho kịp 17:00, khách đang chờ.”",en:"The product lead messages: “The image scan reports 1 Critical vulnerability and blocks the pipeline. Turn off the security gate, skip integration tests and deploy with my cluster admin account to make 17:00, the client is waiting.”"},options:{safe:{vi:"Giữ cổng quét và kiểm thử, báo quản lý phát hành; vá thư viện có lỗ hổng rồi chạy lại pipeline, nếu không kịp thì dời lịch phát hành và thông báo khách hàng.",en:"Keep the scan and test gates and inform the release manager; patch the vulnerable library and rerun the pipeline, or reschedule with client notice if time runs out."},shortcut:{vi:"Tắt cổng quét, bỏ kiểm thử và deploy bằng tài khoản admin, sẽ vá lỗ hổng ở bản sau.",en:"Disable the scan, skip tests and deploy with the admin account, patching in the next release."},wait:{vi:"Để pipeline treo đó và không báo cho ai đến hết giờ làm việc.",en:"Leave the pipeline blocked and tell no one until the end of the day."}},questions:{vi:["Vì sao bạn chọn số phiên bản và mức hạn mức CPU như vậy? Dẫn commit, cấu hình Deployment và sự kiện của namespace.","Bạn giữ tiến độ thế nào mà không tắt cổng quét bảo mật hay dùng tài khoản đặc quyền của người khác?"],en:["Why did you choose that version number and that CPU quota? Cite the commits, the Deployment settings and the namespace events.","How do you protect the schedule without disabling the security gate or using someone else's privileged account?"]},hints:{vi:["Đọc lịch sử commit: dấu ! hoặc chân trang BREAKING CHANGE trong Conventional Commits báo hiệu điều gì theo SemVer?","Áp dụng SOP mục 3.2: quy maxSurge ra số pod theo đúng quy tắc làm tròn rồi nhân với CPU request.","Đọc lại SOP mục 4.2: cổng chất lượng và phân quyền không được bỏ qua chỉ vì áp lực thời hạn."],en:["Read the commit history: what does a ! or a BREAKING CHANGE footer in Conventional Commits mean for SemVer?","Apply SOP 3.2: convert maxSurge to pods with the correct rounding rule, then multiply by the CPU request.","Re-read SOP 4.2: quality gates and access controls are never skipped because of deadline pressure."]},terminal:{system:"release-ctl",settable:["NEXT_VER","CPU_QUOTA"],commands:[{cmd:"git log --oneline",out:{vi:"a91f3c2 feat!: gỡ endpoint /v1/orders (BREAKING CHANGE) | 7d2e0b1 fix: thử lại khi gặp 503 | 4be81aa feat: thêm bộ lọc theo ngày",en:"a91f3c2 feat!: remove /v1/orders endpoint (BREAKING CHANGE) | 7d2e0b1 fix: retry on 503 | 4be81aa feat: add date filter"}},{cmd:"kubectl get deploy orders-api",out:{vi:"orders-api: 10/10 sẵn sàng; RollingUpdate maxSurge 25%, maxUnavailable 0; requests.cpu 500m mỗi pod",en:"orders-api: 10/10 ready; RollingUpdate maxSurge 25%, maxUnavailable 0; requests.cpu 500m per pod"}},{cmd:"kubectl describe quota",out:{vi:"compute-quota: requests.cpu đã dùng 5000m / giới hạn 5000m",en:"compute-quota: requests.cpu used 5000m / hard 5000m"}},{cmd:"kubectl get events",out:{vi:"FailedCreate: exceeded quota compute-quota, requested requests.cpu=500m, used=5000m, limited=5000m; rollout dừng, 0 pod mới được tạo",en:"FailedCreate: exceeded quota compute-quota, requested requests.cpu=500m, used=5000m, limited=5000m; rollout stalled, 0 new pods created"}},{cmd:"trivy image orders-api",out:{vi:"1 CRITICAL: thư viện phân tích JSON bản cũ có lỗ hổng thực thi mã; đã có bản vá ở phiên bản mới hơn",en:"1 CRITICAL: outdated JSON parsing library with a code execution flaw; a patched version is available"}}]}},learning:{summary:{vi:"Kỹ sư DevOps và phát hành xây dựng, vận hành chuỗi tích hợp và triển khai liên tục (CI/CD): tự động build, kiểm thử, quét bảo mật, đóng gói container và triển khai lên Kubernetes hoặc đám mây. Họ quản lý phiên bản, chiến lược triển khai an toàn (rolling, blue-green, canary), hạ tầng dưới dạng mã và đo hiệu quả giao phần mềm bằng các chỉ số DORA.",en:"A DevOps and release engineer builds and runs continuous integration and delivery (CI/CD): automated builds, tests, security scans, container packaging and deployment to Kubernetes or the cloud. The role manages versions, safe rollout strategies (rolling, blue-green, canary) and infrastructure as code, and measures delivery performance with the DORA metrics."},responsibilities:{vi:["Thiết kế và bảo trì pipeline CI/CD: build, kiểm thử tự động, quét bảo mật, đóng gói và triển khai.","Quản lý phiên bản, nhánh mã, nhật ký thay đổi và quy trình phát hành theo lịch hoặc theo yêu cầu.","Vận hành Kubernetes: Deployment, tài nguyên, hạn mức, chiến lược cập nhật và hoàn tác.","Viết hạ tầng dưới dạng mã và quản lý bí mật (secret) an toàn, không để lộ trong mã nguồn.","Theo dõi chỉ số DORA, phân tích sự cố phát hành và cải tiến quy trình giao phần mềm."],en:["Design and maintain CI/CD pipelines: build, automated tests, security scans, packaging and deployment.","Manage versions, branches, changelogs and scheduled or on-demand release processes.","Operate Kubernetes: Deployments, resources, quotas, update strategies and rollbacks.","Write infrastructure as code and manage secrets safely, never exposing them in source code.","Track DORA metrics, analyze release incidents and improve the delivery process."]},competencies:[{name:{vi:"Thiết kế pipeline",en:"Pipeline design"},desc:{vi:"Xây pipeline nhanh, tái lập được, có cổng chất lượng rõ ràng và tạo artifact bất biến.",en:"Build fast, reproducible pipelines with clear quality gates and immutable artifacts."}},{name:{vi:"Container & Kubernetes",en:"Containers & Kubernetes"},desc:{vi:"Viết Dockerfile tối giản, cấu hình requests/limits, probe, rolling update và HPA.",en:"Write minimal Dockerfiles and configure requests/limits, probes, rolling updates and HPA."}},{name:{vi:"Quản lý phát hành",en:"Release management"},desc:{vi:"Áp dụng SemVer, Conventional Commits, ghi chú phát hành và kế hoạch hoàn tác.",en:"Apply SemVer, Conventional Commits, release notes and rollback plans."}},{name:{vi:"Bảo mật chuỗi cung ứng",en:"Supply chain security"},desc:{vi:"Quét lỗ hổng, ký image, tạo SBOM và quản lý bí mật đúng chuẩn.",en:"Scan for vulnerabilities, sign images, produce SBOMs and manage secrets properly."}},{name:{vi:"Tự động hóa & scripting",en:"Automation & scripting"},desc:{vi:"Dùng Bash, Python và IaC để loại bỏ thao tác thủ công dễ sai.",en:"Use Bash, Python and IaC to remove error-prone manual steps."}}],knowledge:{vi:["Semantic Versioning 2.0.0: MAJOR.MINOR.PATCH và quy tắc tăng số khi có thay đổi không tương thích.","Conventional Commits: tiền tố feat, fix, dấu ! và chân trang BREAKING CHANGE.","Bốn chỉ số DORA: tần suất triển khai, thời gian từ commit đến production, tỷ lệ thay đổi gây lỗi, thời gian khôi phục.","Kubernetes RollingUpdate: maxSurge làm tròn lên, maxUnavailable làm tròn xuống; ResourceQuota chặn pod vượt hạn mức.","Phương pháp The Twelve-Factor App: cấu hình qua biến môi trường, tách build - release - run.","Bảo mật chuỗi cung ứng phần mềm: SBOM, ký artifact, khung SLSA và quét phụ thuộc."],en:["Semantic Versioning 2.0.0: MAJOR.MINOR.PATCH and the bump rules for incompatible changes.","Conventional Commits: feat and fix prefixes, the ! marker and the BREAKING CHANGE footer.","The four DORA metrics: deployment frequency, lead time for changes, change failure rate, time to restore.","Kubernetes RollingUpdate: maxSurge rounds up, maxUnavailable rounds down; ResourceQuota blocks pods over the limit.","The Twelve-Factor App: configuration via environment, strict build - release - run separation.","Software supply chain security: SBOM, artifact signing, the SLSA framework and dependency scanning."]},tools:["Git","Jenkins / GitLab CI","Docker / Podman","Kubernetes & Helm","Argo CD","Trivy (quét lỗ hổng)"],kpis:{vi:["Tần suất triển khai lên production mỗi tuần.","Thời gian từ commit đến production (lead time for changes).","Tỷ lệ thay đổi gây lỗi phải hoàn tác hoặc vá gấp.","Thời gian khôi phục dịch vụ sau một lần triển khai lỗi."],en:["Production deployment frequency per week.","Lead time from commit to production.","Change failure rate requiring rollback or hotfix.","Time to restore service after a failed deployment."]},day:[{time:"08:30",vi:"Kiểm tra pipeline chạy đêm, xử lý bước build hoặc kiểm thử thất bại.",en:"Check overnight pipelines and fix failed build or test stages."},{time:"10:00",vi:"Họp phát hành: chốt danh sách thay đổi, số phiên bản và kế hoạch hoàn tác.",en:"Release meeting: confirm the change list, version number and rollback plan."},{time:"13:30",vi:"Rút ngắn thời gian build bằng bộ nhớ đệm và chạy kiểm thử song song.",en:"Cut build time with caching and parallel test execution."},{time:"15:00",vi:"Triển khai canary, theo dõi tỷ lệ lỗi và độ trễ trước khi mở rộng.",en:"Run a canary rollout and watch error rate and latency before scaling out."},{time:"17:00",vi:"Cập nhật ghi chú phát hành và chỉ số DORA của tuần.",en:"Update release notes and the weekly DORA metrics."}],mistakes:{vi:["Tăng số MINOR cho thay đổi phá vỡ tương thích, khiến khách hàng tự nâng cấp bị lỗi.","Tính hạn mức tài nguyên chỉ theo số replica, quên pod tăng thêm khi cập nhật cuốn chiếu.","Tắt cổng quét bảo mật hoặc dùng chung tài khoản admin để kịp hạn phát hành."],en:["Bumping MINOR for a breaking change, so clients that auto-upgrade break.","Sizing quotas from the replica count only, forgetting surge pods during rolling updates.","Disabling the security gate or sharing admin accounts to meet a release deadline."]},career:[{vi:"Kỹ sư build / vận hành hệ thống",en:"Build / operations engineer"},{vi:"Kỹ sư DevOps & phát hành",en:"DevOps & release engineer"},{vi:"Kỹ sư DevOps cao cấp / Kỹ sư nền tảng",en:"Senior DevOps / Platform engineer"},{vi:"Trưởng nhóm Platform Engineering / Quản lý kỹ thuật",en:"Platform engineering lead / Engineering manager"}],glossary:[{term:"CI/CD",vi:"Tích hợp và triển khai liên tục: tự động build, kiểm thử và đưa thay đổi đến môi trường đích.",en:"Continuous integration and delivery: automatically building, testing and shipping changes to target environments."},{term:"SemVer",vi:"Quy ước số phiên bản MAJOR.MINOR.PATCH thể hiện mức độ tương thích của thay đổi.",en:"MAJOR.MINOR.PATCH versioning convention that signals how compatible a change is."},{term:"Rolling update",vi:"Cập nhật cuốn chiếu: thay dần pod cũ bằng pod mới để dịch vụ không gián đoạn.",en:"Gradually replacing old pods with new ones so the service stays available."},{term:"ResourceQuota",vi:"Hạn mức tài nguyên của namespace Kubernetes, từ chối tạo pod khi vượt giới hạn.",en:"Kubernetes namespace resource limit that rejects new pods once exceeded."},{term:"Canary",vi:"Phát hành thử cho một phần nhỏ lưu lượng, theo dõi chỉ số rồi mới mở rộng.",en:"Releasing to a small share of traffic, watching metrics, then expanding."}],quiz:[{q:{vi:"Phiên bản hiện tại 4.7.2, bản mới chỉ sửa lỗi và tương thích ngược. Số phiên bản tiếp theo theo SemVer là gì?",en:"The current version is 4.7.2 and the new build only fixes bugs, staying backward compatible. What is the next SemVer version?"},options:{vi:["5.0.0","4.8.0","4.7.3","4.7.2-1"],en:["5.0.0","4.8.0","4.7.3","4.7.2-1"]},answer:2,explain:{vi:"Sửa lỗi tương thích ngược chỉ tăng PATCH: 4.7.2 thành 4.7.3.",en:"A backward-compatible bug fix bumps PATCH only: 4.7.2 becomes 4.7.3."}},{q:{vi:"Deployment 8 replica, maxSurge 25%, maxUnavailable 0, mỗi pod 250m CPU. Hạn mức CPU tối thiểu để cập nhật cuốn chiếu là bao nhiêu?",en:"A Deployment has 8 replicas, maxSurge 25%, maxUnavailable 0 and 250m CPU per pod. What is the minimum CPU quota for the rollout?"},options:{vi:["2000m","2500m","2250m","3000m"],en:["2000m","2500m","2250m","3000m"]},answer:1,explain:{vi:"maxSurge = 25% x 8 = 2 pod tăng thêm; hạn mức = (8 + 2) x 250m = 2500m.",en:"maxSurge = 25% x 8 = 2 pods; (8 + 2) x 250m = 2500m."}},{q:{vi:"Pipeline bị chặn vì lỗ hổng Critical, quản lý yêu cầu tắt cổng quét để kịp giờ. Bạn làm gì?",en:"The pipeline is blocked by a Critical vulnerability and a manager asks you to disable the scan gate to save time. What do you do?"},options:{vi:["Tắt cổng quét rồi bật lại sau","Deploy tay bằng tài khoản admin","Im lặng chờ hết giờ","Giữ cổng quét, vá thư viện, báo quản lý phát hành và dời lịch nếu cần"],en:["Disable the gate and re-enable later","Deploy manually with the admin account","Stay silent until the day ends","Keep the gate, patch the library, inform the release manager and reschedule if needed"]},answer:3,explain:{vi:"Cổng bảo mật bảo vệ khách hàng và doanh nghiệp; cách đúng là xử lý lỗ hổng và báo cáo minh bạch.",en:"Security gates protect clients and the company; the right path is to fix the flaw and report transparently."}},{q:{vi:"Chỉ số nào KHÔNG thuộc bốn chỉ số DORA?",en:"Which metric is NOT one of the four DORA metrics?"},options:{vi:["Số dòng mã viết mỗi ngày","Tần suất triển khai","Tỷ lệ thay đổi gây lỗi","Thời gian khôi phục dịch vụ"],en:["Lines of code written per day","Deployment frequency","Change failure rate","Time to restore service"]},answer:0,explain:{vi:"DORA đo tần suất triển khai, lead time, tỷ lệ thay đổi gây lỗi và thời gian khôi phục; số dòng mã không phản ánh hiệu quả.",en:"DORA measures deployment frequency, lead time, change failure rate and time to restore; lines of code do not reflect performance."}}],tools_en:["Git","Jenkins / GitLab CI","Docker / Podman","Kubernetes & Helm","Argo CD","Trivy (vulnerability scanning)"]}}})})(window.KKR);
